// Inlines the cburnett piece SVG bodies into js/piece-data.js (run once; output is committed).
import fs from 'node:fs';
const dir = new URL('../assets/pieces/cburnett/', import.meta.url);
const out = {};
for (const c of 'wb') for (const p of 'PNBRQK') {
  const svg = fs.readFileSync(new URL(`${c}${p}.svg`, dir), 'utf8');
  out[c + p] = svg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '').trim();
}
fs.writeFileSync(new URL('../js/piece-data.js', import.meta.url),
  '// Generated by tools/build-piece-data.mjs from the cburnett set by Colin M.L. Burnett (CC BY-SA 3.0 / GPLv2+).\n' +
  'export const RAW = ' + JSON.stringify(out, null, 1) + ';\n');
console.log('ok');
